using System.Diagnostics;
using System.IO;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Markup;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Threading;
using Microsoft.Win32;

namespace LinkLAN.Desktop;
public sealed class MainShell {
 public Window Window{get;} public MainVM VM{get;}=new();public EngineClient Engine{get;}public CancellationTokenSource Lifetime{get;}=new();public bool Exiting{get;private set;}public bool Preview{get;}
 public TreeView Tree=>Find<TreeView>("NetworkTree");
 readonly string[] args;readonly DispatcherTimer poll=new(){Interval=TimeSpan.FromSeconds(2)},save=new(){Interval=TimeSpan.FromMilliseconds(500)};NativeTray? tray;bool polling,ready,saving;bool lastConnected;string notifiedError="";DateTime lastNotice=DateTime.MinValue;Window? settings;
 public T Find<T>(string name)where T:FrameworkElement=>(T)Window.FindName(name);
 public MainShell(EngineClient engine,string[] args,bool preview){Engine=engine;this.args=args;Preview=preview;Window=(Window)XamlReader.Parse(Resource.Text("MainWindow.xaml"));Window.DataContext=VM;
  using(var stream=Resource.Open("logo.png")){var image=new BitmapImage();image.BeginInit();image.CacheOption=BitmapCacheOption.OnLoad;image.StreamSource=stream;image.EndInit();image.Freeze();Find<Image>("BrandImage").Source=image;Window.Icon=image;}
  Find<Button>("CloseButton").Click+=(_,_)=>Hide();Find<Button>("MinimizeButton").Click+=(_,_)=>Hide();Find<Button>("PowerButton").Click+=async(_,_)=>await Power();Find<Button>("StatusButton").Click+=(_,_)=>{if(VM.State.Error!="")Dialog.Message(this,VM.L["Ошибка подключения"],VM.State.Error);};Find<Button>("OwnIpButton").Click+=(_,_)=>Copy(VM.State.OwnIp);
  Menu("SettingsMenu",()=>OpenSettings());Menu("ChangeNameMenu",()=>OpenSettings(4));Menu("FirewallMenu",async()=>{if(Dialog.Confirm(this,VM.L["Исключения брандмауэра…"],VM.L["Разрешить LinkLAN в брандмауэре Windows?"]))await Run("firewall");});Menu("AdminMenu",Admin);Menu("ExitMenu",async()=>await Quit());Menu("CreateMenu",()=>Dialogs.Network(this,true));Menu("JoinMenu",()=>Dialogs.Network(this,false));
  Menu("DocsMenu",()=>Open("https://github.com/andluk87/linklan#readme"));Menu("SupportMenu",()=>Open("https://github.com/andluk87/linklan/issues"));Menu("UpdatesMenu",()=>Open("https://github.com/andluk87/linklan/releases/latest"));Menu("AboutMenu",()=>Dialog.Message(this,VM.L["О программе LinkLAN"],"LinkLAN "+VM.State.Version+"\nC# / WPF · Go / Wintun\nhttps://github.com/andluk87/linklan"));Menu("LogMenu",()=>{string path=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),"LinkLAN","client.log");if(File.Exists(path))Open(path);else Dialog.Message(this,VM.L["Просмотреть журнал"],VM.L["Журнал пока пуст."]);});
  Tree.SelectedItemChanged+=(_,e)=>VM.SelectedNode=e.NewValue as NodeVM;Tree.PreviewMouseRightButtonDown+=(_,e)=>{var item=Ancestor<TreeViewItem>(e.OriginalSource as DependencyObject);if(item!=null){item.IsSelected=true;VM.SelectedNode=item.DataContext as NodeVM;}};Tree.ContextMenuOpening+=(_,e)=>{var node=VM.SelectedNode;if(node==null){e.Handled=true;return;}Tree.ContextMenu=Context(node);};Tree.ContextMenu=new ContextMenu();
  Tree.MouseDoubleClick+=(_,e)=>{if(VM.SelectedNode is {IsNetwork:false} node){Dialogs.Properties(this,node);e.Handled=true;}};
  Window.PreviewKeyDown+=(_,e)=>{if(e.Key==Key.Insert){Dialogs.Network(this,true);e.Handled=true;}else if(e.Key==Key.Escape){Hide();e.Handled=true;}};
  Window.Closing+=(_,e)=>{if(!Exiting){e.Cancel=true;Hide();}};Window.StateChanged+=(_,_)=>{if(Window.WindowState==WindowState.Minimized)Hide();};Window.SizeChanged+=(_,_)=>QueueSave();Window.LocationChanged+=(_,_)=>QueueSave();VM.ExpansionChanged+=(_,_)=>QueueSave();
  poll.Tick+=async(_,_)=>await Refresh();save.Tick+=async(_,_)=>{save.Stop();await SaveWindow();};SystemEvents.UserPreferenceChanged+=ThemeChanged;
 }
 void Menu(string name,Action action)=>Find<MenuItem>(name).Click+=(_,_)=>action();
 public async Task Initialize(){await Refresh(true);var p=VM.Settings;Appearance.Apply(p.Theme,true);VM.RefreshAppearance();if(p.Window.Width>=250&&p.Window.Height>=350){Window.Width=p.Window.Width;Window.Height=p.Window.Height;}if(p.WindowDip&&p.Window.Positioned){var area=SystemParameters.VirtualScreenWidth;double x=p.Window.X,y=p.Window.Y;if(x+Window.Width>SystemParameters.VirtualScreenLeft&&x<SystemParameters.VirtualScreenLeft+area&&y+32>SystemParameters.VirtualScreenTop&&y<SystemParameters.VirtualScreenTop+SystemParameters.VirtualScreenHeight){Window.Left=x;Window.Top=y;Window.WindowStartupLocation=WindowStartupLocation.Manual;}else Window.WindowStartupLocation=WindowStartupLocation.CenterScreen;}else Window.WindowStartupLocation=WindowStartupLocation.CenterScreen;ready=true;lastConnected=VM.Connected;}
 public void Start(){Window.Show();if(!Preview){tray=new NativeTray(Window,Restore,()=>TrayMenu(),async()=>await Quit());if(tray.Available&&!args.Contains("--show")&&VM.Settings.Server!=""&&(args.Contains("--start-in-tray")||VM.Settings.StartInTray))Window.Hide();}poll.Start();if(!Preview&&VM.Settings.Server=="")OpenSettings(4);}
 public void Restore(){Window.Show();Window.ShowInTaskbar=true;Window.WindowState=WindowState.Normal;Window.Activate();}
 public void Hide(){if(Preview||tray?.Available!=true){Window.WindowState=WindowState.Minimized;return;}Window.Hide();Window.ShowInTaskbar=false;}
 public async Task Quit(){if(Exiting)return;Exiting=true;poll.Stop();save.Stop();await SaveWindow();Lifetime.Cancel();SystemEvents.UserPreferenceChanged-=ThemeChanged;tray?.Dispose();settings?.Close();await Engine.DisposeAsync();Window.Close();Application.Current.Shutdown();}
 public async Task Refresh(bool initial=false){if(polling)return;polling=true;try{var state=await Engine.State();VM.Apply(state);if(Appearance.Apply(state.Settings.Theme))VM.RefreshAppearance();if(ready&&!Preview&&state.Connected!=lastConnected){Notify(state.Connected?VM.L["В сети"]:VM.L["Не в сети"],VM.ComputerName+" · "+VM.OwnIp);lastConnected=state.Connected;}if(ready&&!Preview&&state.Error!=""&&state.Error!=notifiedError){Notify(VM.L["Ошибка подключения"],state.Error);notifiedError=state.Error;}if(state.Error=="")notifiedError="";tray?.Update(VM.Badge);}catch(Exception e){if(initial)throw;poll.Stop();Dialog.Message(this,VM.L["Ошибка запуска"],e.Message);await Quit();}finally{polling=false;}}
 void Notify(string title,string message){if((DateTime.UtcNow-lastNotice).TotalSeconds<30)return;lastNotice=DateTime.UtcNow;tray?.Notify(title,message,VM.Settings);}
 void ThemeChanged(object sender,UserPreferenceChangedEventArgs e){if(Exiting)return;Window.Dispatcher.BeginInvoke(()=>{if(Appearance.Apply(VM.Settings.Theme))VM.RefreshAppearance();});}
 public async Task<JsonElement?> Run(string method,object? parameters=null){try{var result=await Engine.Call(method,parameters);await Refresh();return result;}catch(Exception e){Dialog.Message(this,VM.L["Ошибка"],e.Message);return null;}}
 public async Task Patch(object patch){await Engine.Call("settings",patch);await Refresh();}
 public async Task Power(){if(VM.State.Wanted||VM.Connected){await Run("disconnect");return;}var n=VM.SelectedNode?.Network??VM.State.Networks.FirstOrDefault(n=>n.Id==VM.State.ActiveNetworkId)??VM.State.Networks.FirstOrDefault(n=>n.Status=="approved"&&!n.Blocked);if(!VM.State.ApiReady){OpenSettings(4);return;}if(n==null){Dialogs.Network(this,false);return;}await Run("connect",new{networkId=n.Id});}
 public void OpenSettings(int page=0){if(settings!=null){settings.Activate();return;}settings=Dialogs.Settings(this,page);settings.Closed+=(_,_)=>settings=null;settings.Show();}
 void Admin(){if(Uri.TryCreate(VM.Settings.Server,UriKind.Absolute,out var uri)&&uri.Scheme is "https" or "http")Open(AdminAddress(uri));else OpenSettings(4);}
 public static string AdminAddress(Uri uri){string path=uri.AbsolutePath.TrimEnd('/');if(path.EndsWith("/api",StringComparison.Ordinal))path=path[..^4];return uri.GetLeftPart(UriPartial.Authority)+path+"/api/admin";}
 public void Copy(string value){if(value==""||value=="—")return;try{Clipboard.SetText(value);}catch(Exception e){Dialog.Message(this,VM.L["Ошибка"],e.Message);}}
 public void Open(string value){try{Process.Start(new ProcessStartInfo(value){UseShellExecute=true});}catch(Exception e){Dialog.Message(this,VM.L["Ошибка"],e.Message);}}
 public void Launch(string exe,params string[] values){try{var start=new ProcessStartInfo(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),exe)){UseShellExecute=true};foreach(var value in values)start.ArgumentList.Add(value);Process.Start(start);}catch(Exception e){Dialog.Message(this,VM.L["Ошибка"],e.Message);}}
 ContextMenu TrayMenu(){var menu=new ContextMenu();Add(menu,"Открыть LinkLAN",Restore);Add(menu,"Настройки…",()=>{Restore();OpenSettings();});Add(menu,VM.State.Wanted?"Отключиться":"Подключиться",async()=>await Power());menu.Items.Add(new Separator());Add(menu,"Выход",async()=>await Quit());return menu;}
 ContextMenu Context(NodeVM node){var menu=new ContextMenu();string id=node.NetworkId;if(node.IsNetwork){Add(menu,"Подключиться",async()=>await Run("connect",new{networkId=id}),node.Network.Status=="approved"&&!node.Network.Blocked);Add(menu,"Обновить",async()=>await Run("refresh"));if(node.Network.OwnerId==VM.State.UserId)Add(menu,"Создать приглашение…",async()=>{var result=await Run("invite",new{networkId=id});if(result is JsonElement token&&token.ValueKind==JsonValueKind.String)Dialog.Message(this,VM.L["Код приглашения"],token.GetString()??"",true);});menu.Items.Add(new Separator());Add(menu,node.Network.OwnerId==VM.State.UserId?"Удалить сеть…":"Покинуть сеть…",async()=>{if(Dialog.Confirm(this,node.Name,VM.L["Подтвердить действие?"]))await Run(node.Network.OwnerId==VM.State.UserId?"delete":"leave",new{networkId=id});});}else{Add(menu,"Копировать IP-адрес",()=>Copy(node.Ip));Add(menu,"Пинг",()=>{if(System.Net.IPAddress.TryParse(node.Ip,out _))Launch("ping.exe","-t",node.Ip);});Add(menu,"Общие папки",()=>{if(System.Net.IPAddress.TryParse(node.Ip,out _))Open("\\\\"+node.Ip);});Add(menu,"Удалённый рабочий стол",()=>{if(System.Net.IPAddress.TryParse(node.Ip,out _))Launch("mstsc.exe","/v:"+node.Ip);});menu.Items.Add(new Separator());Add(menu,"Свойства",()=>Dialogs.Properties(this,node));if(node.Network.OwnerId==VM.State.UserId&&node.Peer?.Id!=VM.State.DeviceId){menu.Items.Add(new Separator());if(node.Peer?.Status=="pending")Add(menu,"Одобрить устройство",async()=>await Run("approve-member",new{networkId=id,peerId=node.Id}));Add(menu,"Заблокировать устройство",async()=>{if(Dialog.Confirm(this,node.Name,VM.L["Подтвердить действие?"]))await Run("block-member",new{networkId=id,peerId=node.Id});});Add(menu,"Удалить устройство",async()=>{if(Dialog.Confirm(this,node.Name,VM.L["Подтвердить действие?"]))await Run("remove-member",new{networkId=id,peerId=node.Id});});}}return menu;}
 void Add(ContextMenu menu,string label,Action action,bool enabled=true){var item=new MenuItem{Header=VM.L[label],IsEnabled=enabled};item.Click+=(_,_)=>action();menu.Items.Add(item);}
 void QueueSave(){if(!ready||Exiting||Preview)return;save.Stop();save.Start();}
 public async Task SaveWindow(){if(!ready||Preview||saving)return;saving=true;try{var r=Window.WindowState==WindowState.Normal?new Rect(Window.Left,Window.Top,Window.Width,Window.Height):Window.RestoreBounds;if(!double.IsNaN(r.X)&&r.Width>=250&&r.Height>=350)await Engine.Call("settings",new{window=new WindowPosition{X=(int)r.X,Y=(int)r.Y,Width=(int)r.Width,Height=(int)r.Height,Positioned=true},expanded=VM.Expanded});}catch(Exception e){Program.Log(e);}finally{saving=false;}}
 static T? Ancestor<T>(DependencyObject? element)where T:DependencyObject{while(element!=null){if(element is T value)return value;element=element is Visual?VisualTreeHelper.GetParent(element):LogicalTreeHelper.GetParent(element);}return null;}
}
